{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.izf_sku_style_summary_fact_items as select s.sku_style style, s.sku_size size, s.style_image image, date_trunc(date(order_date), week(monday)) as order_week, sum(ifnull(Selling_price,0)) total_sales, count(distinct order_id) total_orders, sum(ifnull(quantity,0)) total_quantity, avg(ifnull(customer_return_rate,0)) customer_return_rate, avg(ifnull(rto_rate,0)) rto_rate, avg(ifnull(overall_return_rate,0)) overall_return_rate, avg(ifnull(i.Available_Inventory,0)) Available_Inventory, avg(ifnull(sa.ctr,0)) CTR, avg(ifnull(sa.clicks,0)) Clicks, avg(ifnull(sa.total_impressions,0)) Impressions, avg(ifnull(sa.total_add_to_carts,0)) total_add_to_carts, avg(ifnull(sa.Conversion_Rate,0)) Conversion_Rate, avg(ifnull(sa.Return_percent,0)) Return_percent from maplemonk.izf_sales_consolidated s left join ( SELECT `SKU_STYLE` AS `SKU_STYLE`, SAFE_DIVIDE( count(DISTINCT CASE WHEN lower(return_type) = \'return\' THEN ordeR_id END), count(DISTINCT order_id) ) AS `customer_return_rate`, SAFE_DIVIDE( count(DISTINCT CASE WHEN lower(return_type) = \'rto\' THEN ordeR_id END), count(DISTINCT order_id) ) AS `rto_rate`, SAFE_DIVIDE( count(DISTINCT CASE WHEN lower(return_type) = \'rto\' THEN ordeR_id END) + count(DISTINCT CASE WHEN lower(return_type) = \'return\' THEN ordeR_id END), count(DISTINCT order_id) ) AS `overall_return_rate` FROM `MapleMonk`.`izf_returns_consolidated` WHERE order_date >= DATE_ADD(CURRENT_DATE(), INTERVAL -37 DAY) AND order_date < DATE_ADD(CURRENT_DATE(), INTERVAL -7 DAY) GROUP BY 1 ) r on lower(s.sku_style) = lower(r.sku_style) left join ( select sku_style, sku_size, sum(ifnull(Available_Inventory,0)) Available_Inventory from maplemonk.izf_inventory_fact_items where date_diff(current_date(),data_fetch_date,DAY) = 1 group by 1,2 ) i on lower(s.sku_style) = lower(i.sku_style) and lower(s.sku_size) = lower(i.sku_size) left join (select Brand, date_trunc(date(week), week(monday)) as order_week, cast(ctr__ as float64)/100 as ctr, Gender, cast(avg_RPLC as float64)/100 as avg_RPLC, cast(ATC_rate__ as float64)/100 as ATC_rate, sa.Article_Type, SPLIT(mm.Article_no, \'-\')[OFFSET(0)] as Style, cast(total_clicks as int64) Clicks, cast(avg_Seller_MRP as int64) avg_Seller_MRP, cast(total_purchases as int64) total_purchases, cast(Conversion_rate__ as float64)/100 as Conversion_Rate, cast(total_impressions as int64) total_impressions, cast(total_add_to_carts as int64) total_add_to_carts, cast(Return___weighted as float64)/100 as Return_percent from maplemonk.gs_myntra_search_analytics sa left join maplemonk.gs_myntra_sku_mapping mm on replace(mm.style_id,\' \',\'\') = cast(sa.style_id as string) ) sa on lower(s.sku_style) = lower(sa.style) and sa.order_week = date_trunc(date(s.order_date), week(monday)) where lower(marketplace) like \'%myntra%\' and not(lower(oms_order_status) like \'%cancel%\' or lower(order_status) like \'%cancel%\') group by 1,2,3,4; create or replace table maplemonk.izf_myntra_style_performance_report as with inventory as ( select sku_style, sum(ifnull(SOLD_QUANTITY_7_DAYS,0))/7 as ROS_7D, sum(ifnull(SOLD_QUANTITY_10_DAYS,0))/10 as ROS_10D, sum(ifnull(SOLD_QUANTITY_10_DAYS,0))/10 as ROS_15D, sum(available_inventory) as current_inventory, from maplemonk.izf_inventory_fact_items where date_diff(current_date(),data_fetch_date,DAY) = 1 group by 1 ), myntra_search_performance as ( SELECT CASE WHEN SAFE_CAST(week AS INT64) IS NOT NULL AND SAFE_CAST(week AS INT64) >= 1826 THEN DATE_ADD(DATE \'1900-01-01\',INTERVAL (SAFE_CAST(week AS INT64) - 2) DAY) WHEN week = \'27-10-20225\' then \'2025-10-27\' WHEN SAFE_CAST(week AS STRING) IS NOT NULL AND SAFE_CAST(week AS STRING) LIKE \'%-%-%\' THEN PARSE_DATE(\'%d-%m-%Y\', SAFE_CAST(week AS STRING)) ELSE NULL END AS Week_of, Style, safe_cast(Volume as int64) as Volume, userQuery as search_keyword, safe_cast(totalClicks as int64) Clicks, safe_cast(organicClicksShare as float64)/100 * safe_cast(totalClicks as int64) as Organic_Clicks, safe_cast(productCount as int64) search_product_count, safe_cast(totalImpressions as int64) Impressions, safe_cast(organicImpressionsShare as float64)/100 * safe_cast(totalImpressions as int64) as Organic_Impressions from maplemonk.izf_myntra_search_performance ), style_search_performance as ( select style, week_of, array_agg(search_keyword) as search_keywords, sum(ifnull(volume,0)) as volume, sum(ifnull(search_product_count,0)) as search_product_count, sum(ifnull(Clicks,0)) as Clicks, sum(ifnull(Organic_Clicks,0)) as Organic_Clicks, sum(ifnull(Impressions,0)) as Impressions, sum(ifnull(Organic_Impressions,0)) as Organic_Impressions from myntra_search_performance group by 1,2 ) select style, week_of, search_keywords, volume, search_product_count, Clicks, Organic_Clicks, Impressions, Organic_Impressions, ROS_7D, ROS_10D, ROS_15D, current_inventory, from style_search_performance s left join inventory i on i.sku_style = s.style ;",
                    "transaction": true
                }
            ) }}
